pub(super) const fn count() -> usize {
    STUBS.len()
}

pub(super) fn definitions() -> Vec<CardDefinition> {
    STUBS
        .iter()
        .map(|stub| {
            let record = CardRecord::unimplemented(
                PrintingAnchor::scryfall(stub.anchor),
                stub.name,
                stub.debut_set,
            );
            let mut definition = record.definition();
            definition.printings = stub
                .printings
                .iter()
                .copied()
                .map(|set| CardPrinting::new(definition.id, set))
                .collect();
            definition
        })
        .collect()
}

pub(super) fn apply_format_printings(definitions: &mut [CardDefinition]) {
    let indices = definitions
        .iter()
        .enumerate()
        .map(|(index, definition)| (definition.name.clone(), index))
        .collect::<HashMap<_, _>>();
    for printing in FORMAT_PRINTINGS {
        let index = *indices
            .get(printing.name)
            .unwrap_or_else(|| panic!("missing catalog definition for {}", printing.name));
        let definition = &mut definitions[index];
        if !definition
            .printings
            .iter()
            .any(|known| known.id.set == printing.set)
        {
            definition
                .printings
                .push(CardPrinting::new(definition.id, printing.set));
        }
    }
}

#[cfg(test)]
pub(super) fn uncataloged_format_printings(
    catalog: &crate::card::CardCatalog,
    format: crate::Format,
) -> Vec<&'static str> {
    let mut names = FORMAT_PRINTINGS
        .iter()
        .filter(|printing| format.allows_set(printing.set))
        .filter_map(|printing| match catalog.find_by_name(printing.name) {
            Some(definition) if catalog.has_printing_in(definition, printing.set) => None,
            _ => Some(printing.name),
        })
        .collect::<Vec<_>>();
    names.sort_unstable();
    names.dedup();
    names
}
